@F.udf(TimestampType())
def parse_twitter_timestamp(value):
    if value is None:
        return None

    try:
        return datetime.strptime(
            value,
            "%a %b %d %H:%M:%S %z %Y"
        ).replace(tzinfo=None)
    except Exception:
        return None


tweets_session = (
    tweets

    .withColumn(
        "tweet_timestamp_utc",
        parse_twitter_timestamp(
            F.col("tweet_created_at")
        )
    )

    .withColumn(
        "tweet_timestamp_et",
        F.from_utc_timestamp(
            F.col("tweet_timestamp_utc"),
            "America/New_York"
        )
    )

    .withColumn(
        "tweet_date_et",
        F.to_date("tweet_timestamp_et")
    )
)


tweets_session.agg(
    F.count("*").alias("rows"),
    F.countDistinct("tweet_id").alias("distinct_tweets"),

    F.sum(
        F.col("tweet_timestamp_utc")
        .isNull()
        .cast("int")
    ).alias("null_utc"),

    F.sum(
        F.col("tweet_timestamp_et")
        .isNull()
        .cast("int")
    ).alias("null_et")

).show()

nltk.download("vader_lexicon", quiet=True)

from nltk.sentiment.vader import SentimentIntensityAnalyzer

sia = SentimentIntensityAnalyzer()


@F.udf(DoubleType())
def vader_compound(text):

    if text is None:
        return 0.0

    try:
        return float(
            sia.polarity_scores(text)["compound"]
        )
    except Exception:
        return 0.0


print("VADER ready.")
